(()=>{
 const rows=[];for(const format of [null,'%s','%d','%i','%f','%o','%O','%c','%%','%s %d','x %s y','%q'])for(const kind of ['object','throw','symbol','proxy','native']){const effects=[];let value;if(kind==='object'||kind==='throw')value={toString(){effects.push('string');if(kind==='throw')throw Error('sentinel');return '12.75'},valueOf(){effects.push('value');return 99}};if(kind==='symbol')value=Symbol('token');if(kind==='native')value=document.body;if(kind==='proxy')value=new Proxy({},{get(t,k){effects.push('get:'+String(k));throw Error('proxy')}});let error=null;try{if(format===null)console.log(value);else console.log(format,value)}catch(e){error={name:e.name,message:e.message}}rows.push({format,kind,effects,error})}return rows})()
